  "code": "import re\n\n\n_HEADING_HINTS = (\n    \"index to exhibits\",\n    \"exhibit index\",\n    \"item 15. exhibits\",\n    \"item 15 exhibits\",\n    \"exhibits, financial statement schedules\",\n)\n\n_NOISE_PREFIXES = (\n    \"incorporated by reference\",\n    \"table of contents\",\n    \"exhibit number\",\n    \"exhibit description\",\n    \"form\",\n    \"filing date\",\n    \"sec file no.\",\n    \"filed herewith\",\n    \"pursuant to the requirements\",\n    \"signatures\",\n    \"power of attorney\",\n    \"page \",\n)\n\n_KEYWORD_BONUS = (\n    \"description of securities\",\n    \"credit agreement\",\n    \"loan agreement\",\n    \"revolving credit agreement\",\n    \"indenture\",\n    \"note due\",\n    \"guaranteed senior note\",\n    \"employment agreement\",\n    \"share purchase agreement\",\n    \"stock purchase plan\",\n    \"stock incentive plan\",\n    \"employee stock purchase plan\",\n    \"employee stock plan\",\n    \"wafer supply agreement\",\n    \"severance plan\",\n    \"deferred compensation\",\n    \"restricted stock\",\n    \"amendment to\",\n    \"amended and restated\",\n    \"agreement\",\n    \"plan\",\n    \"note\",\n    \"securities\",\n)\n\n\ndef rule_exhibit_index_candidates(doc: dict) -> list[dict]:\n    try:\n        lines = [item for item in (doc.get(\"lines\") or []) if isinstance(item, dict)]\n        if not lines:\n            return []\n\n        def norm(text: str) -> str:\n            text = re.sub(r\"\\s+\", \" \", (text or \"\")).strip()\n            text = re.sub(r\"\\s*\\.\\s*\", \".\", text)\n            return text\n\n        def is_noise(text: str) -> bool:\n            low = norm(text).lower()\n            if not low:\n                return True\n            if low.isdigit():\n                return True\n            if any(low.startswith(prefix) for prefix in _NOISE_PREFIXES):\n                return True\n            return False\n\n        def parse_exhibit_line(text: str) -> tuple[str | None, str]:\n            raw = norm(text)\n            if not raw:\n                return None, \"\"\n\n            compact = raw.replace(\" \", \"\")\n            match = re.match(r\"(?i)^exhibit(?:\\s+)?((?:\\d+(?:\\.\\d+)*[A-Za-z]?)|\\d{3})\\b[:\\s-]*(.*)$\", raw)\n            if match:\n                num = match.group(1).replace(\" \", \"\")\n                desc = match.group(2).strip()\n                return num, desc\n\n            match = re.match(r\"^(\\d+\\.\\d+(?:\\.\\d+)*[A-Za-z]?)\\b[:\\s-]*(.*)$\", compact)\n            if match:\n                num = match.group(1)\n                desc = norm(match.group(2))\n                return num, desc\n\n            return None, \"\"\n\n        def looks_like_exhibit_row(text: str) -> bool:\n            num, _ = parse_exhibit_line(text)\n            if not num:\n                return False\n            if \".\" not in num and not re.search(r\"[A-Za-z]$\", num):\n                return False\n            return True\n\n        def exhibit_cluster_score(start_idx: int) -> int:\n            score = 0\n            for j in range(start_idx, min(len(lines), start_idx + 80)):\n                if looks_like_exhibit_row(lines[j].get(\"text\") or \"\"):\n                    score += 1\n            return score\n\n        candidate_starts: list[int] = []\n        for idx, item in enumerate(lines):\n            text = norm(item.get(\"text\") or \"\")\n            low = text.lower()\n            if not text:\n                continue\n            if any(hint in low for hint in _HEADING_HINTS):\n                candidate_starts.append(idx)\n                continue\n            if (\"exhibit\" in low and (\"number\" in low or \"description\" in low)) and exhibit_cluster_score(idx) >= 2:\n                candidate_starts.append(idx)\n\n        if candidate_starts:\n            start_idx = max(candidate_starts)\n        else:\n            clustered = [\n                idx\n                for idx, item in enumerate(lines)\n                if looks_like_exhibit_row(item.get(\"text\") or \"\") and exhibit_cluster_score(idx) >= 3\n            ]\n            if not clustered:\n                return [{\"text\": \"none listed\"}]\n            start_idx = max(clustered)\n\n        spans: list[dict] = []\n        seen: set[str] = set()\n        idx = start_idx\n        while idx < len(lines):\n            line = norm(lines[idx].get(\"text\") or \"\")\n            if not line:\n                idx += 1\n                continue\n\n            num, desc = parse_exhibit_line(line)\n            if not num:\n                idx += 1\n                continue\n\n            if \".\" not in num and not re.search(r\"[A-Za-z]$\", num):\n                idx += 1\n                continue\n\n            parts: list[str] = []\n            if desc and not is_noise(desc):\n                parts.append(desc)\n\n            j = idx + 1\n            while j < len(lines) and len(parts) < 3:\n                nxt = norm(lines[j].get(\"text\") or \"\")\n                if not nxt:\n                    j += 1\n                    continue\n                if looks_like_exhibit_row(nxt):\n                    break\n                if is_noise(nxt):\n                    j += 1\n                    continue\n                parts.append(nxt)\n                j += 1\n\n            desc_text = norm(\" \".join(parts)).strip(\" .;:-\")\n            if not desc_text:\n                idx += 1\n                continue\n\n            # Avoid returning boilerplate headers or page artifacts as answers.\n            if desc_text.lower() in {\"table of contents\", \"incorporated by reference\"}:\n                idx += 1\n                continue\n\n            canonical = f\"Exhibit {num}: {desc_text}\"\n            if canonical not in seen:\n                span = {\"text\": canonical}\n                for key in (\"page_no\", \"line_no\"):\n                    if key in lines[idx]:\n                        span[key] = lines[idx][key]\n                spans.append(span)\n                seen.add(canonical)\n\n            idx = j if j > idx else idx + 1\n\n        if not spans:\n            return [{\"text\": \"none listed\"}]\n\n        def sort_key(span: dict) -> tuple[int, int, int]:\n            text = span.get(\"text\", \"\")\n            m = re.match(r\"^Exhibit\\s+([0-9]+(?:\\.[0-9]+)*(?:[A-Za-z]?)?)\\s*:\\s*(.*)$\", text)\n            if not m:\n                return (9, 9, 9)\n            num = m.group(1)\n            desc = m.group(2).lower()\n            bonus = 0\n            if \"description of securities\" in desc:\n                bonus -= 50\n            if num.startswith(\"10.\"):\n                bonus -= 20\n            elif num.startswith(\"4.\"):\n                bonus -= 10\n            if any(keyword in desc for keyword in _KEYWORD_BONUS):\n                bonus -= 5\n            # Preserve document order as a stable tie-breaker.\n            page = int(span.get(\"page_no\", 10**9)) if str(span.get(\"page_no\", \"\")).isdigit() else 10**9\n            line = int(span.get(\"line_no\", 10**9)) if str(span.get(\"line_no\", \"\")).isdigit() else 10**9\n            return (bonus, page, line)\n\n        spans.sort(key=sort_key)\n        return spans[:80]\n    except Exception:\n        return []\n",
