from pathlib import Path
rule_path=Path('/mnt/data/LSF/rules/financebench/agentic_rule_full_data_gpt54mini/all_docs/q06_list_one_material_agreement_or_other_exhibit_number_explicit/rule_exhibit_index_candidates.py')
