for doc_name in ['ADOBE_2022_10K','AMAZON_2022_10K','AMCOR_2023_10K','BESTBUY_2020_10K']:
    import subprocess, json
    # use helper to get raw text then minimal parse into lines would be painful; instead use manifest file directly for doc path
    mf=json.load(open(manifest))
    doc_path=next(x['doc_path'] for x in mf if x['doc_name']==doc_name)
    lines=[{'text':line.rstrip('\\n')} for line in open(doc_path, encoding='utf-8', errors='ignore').read().splitlines()]
    def norm(text: str) -> str:
        text = re.sub(r'\\s+', ' ', (text or '')).strip(); text = re.sub(r'\\s*\\.\\s*', '.', text); return text
    def parse_exhibit_line(text: str):
        raw = norm(text)
        if not raw: return None, ''
        compact = raw.replace(' ', '')
        match = re.match(r'(?i)"'^exhibit(?:'"\\s+)?((?:\\d+(?:\\.\\d+)*[A-Za-z]?)|\\d{3})\\b[:\\s-]*(.*)"'$'"', raw)
        if match:
            return match.group(1).replace(' ', ''), match.group(2).strip()
        match = re.match(r'"'^('"\\d+\\.\\d+(?:\\.\\d+)*[A-Za-z]?)\\b[:\\s-]*(.*)"'$'"', compact)
        if match:
            return match.group(1), norm(match.group(2))
        return None, ''
    def looks_like_exhibit_row(text: str)->bool:
        num,_=parse_exhibit_line(text)
        return bool(num and ('.' in num or re.search(r'[A-Za-z]"'$'"', num)))
    def exhibit_cluster_score(start_idx: int) -> int:
        return sum(1 for j in range(start_idx, min(len(lines), start_idx+80)) if looks_like_exhibit_row(lines[j].get('text') or ''))
    candidates=[]
    for idx,item in enumerate(lines):
        text=norm(item.get('text') or '')
        low=text.lower()
        if not text: continue
        if any(h in low for h in mod._HEADING_HINTS):
            candidates.append((idx, exhibit_cluster_score(idx), text))
            continue
        if ('exhibit' in low and ('number' in low or 'description' in low)) and exhibit_cluster_score(idx) >= 2:
            candidates.append((idx, exhibit_cluster_score(idx), text))
    print('\\nDOC', doc_name)
    print('top candidates', sorted(candidates, key=lambda x:(-x[1], x[0]))[:10])
